private void assorteddamagenumbers_rememberDamageSource(DamageSource source, CallbackInfo ci) {
    DamageNumbers.onDamageEvent((LivingEntity) (Object) this, source);
}

public static void onDamageEvent(LivingEntity entity, DamageSource source) {
    if (entity.level().isClientSide()) {
        recentSources.put(entity.getId(), source);
        recentSourceTimes.put(entity.getId(), entity.level().getGameTime());
    }
}

private static void spawn(Minecraft minecraft, ClientLevel level, LivingEntity entity, String amount, Component label, int color) {
    MutableComponent text = Component.literal(amount);
    if (DamageNumbersClient.CONFIG.damageNumbersShowSource.get()) {
        text.append(" (").append(label).append(")");
    }

    // Out in front of the creature on the viewer's side, or its own head hides the number.
    Vec3 toViewer = minecraft.gameRenderer.mainCamera().position().subtract(entity.position()).multiply(1.0D, 0.0D, 1.0D);
    Vec3 front = toViewer.lengthSqr() < 1.0E-4D ? Vec3.ZERO : toViewer.normalize().scale(entity.getBbWidth() / 2.0D + 0.3D);

    float offset = -minecraft.font.width(text) / 2.0F;
    popups.add(new DamagePopup(text.getVisualOrderText(), offset, color, DamageNumbersClient.CONFIG.damageNumbersLifetime.get(),
            entity.getX() + front.x, entity.getY() + entity.getBbHeight() * 0.8D, entity.getZ() + front.z, entity.getY() + 0.25D, level.getRandom()));
}

private static Component label(DamageKind kind, @Nullable DamageSource source) {
    if (source != null && kind == DamageKind.MELEE && source.getEntity() != null) {
        if (source.getEntity() instanceof Player attacker) {
            ItemStack weapon = attacker.getMainHandItem();
            return weapon.isEmpty() ? kind.label() : weapon.getHoverName();
        }
        return source.getEntity().getName();
    }
    if (source != null && kind == DamageKind.PROJECTILE && source.getDirectEntity() != null) {
        return source.getDirectEntity().getName();
    }
    return kind.label(source);
}

public static void submit(PoseStack poseStack, SubmitNodeCollector collector, CameraRenderState camera) {
    if (popups.isEmpty()) {
        return;
    }

    float partialTick = Minecraft.getInstance().getDeltaTracker().getGameTimeDeltaPartialTick(false);
    Vec3 cam = camera.pos;
    for (DamagePopup popup : popups) {
        int alpha = popup.alpha(partialTick);
        if (alpha <= 0) {
            continue;
        }

        poseStack.pushPose();
        poseStack.translate(Mth.lerp(partialTick, popup.lastX, popup.x) - cam.x, Mth.lerp(partialTick, popup.lastY, popup.y) - cam.y, Mth.lerp(partialTick, popup.lastZ, popup.z) - cam.z);
        poseStack.rotate(camera.orientation);
        poseStack.scale(TEXT_SCALE, -TEXT_SCALE, TEXT_SCALE);
        // 1.2.5 drew the number four times around itself in the background colour; an outline is the same look.
        collector.submitText(poseStack, popup.offset, 0.0F, popup.text, false, Font.DisplayMode.NORMAL, LightCoordsUtil.FULL_BRIGHT,
                alpha << 24 | popup.color, 0, alpha << 24);
        poseStack.popPose();
    }
}

public DamagePopup(FormattedCharSequence text, float offset, int color, int lifetime, double x, double y, double z, double floor, RandomSource random) {
    this.text = text;
    this.offset = offset;
    this.color = color;
    this.lifetime = lifetime;
    this.floor = floor;
    this.x = this.lastX = x;
    this.y = this.lastY = y;
    this.z = this.lastZ = z;
    this.motionX = (random.nextDouble() - 0.5D) * 0.2D;
    this.motionY = 0.15D + random.nextDouble() * 0.15D;
    this.motionZ = (random.nextDouble() - 0.5D) * 0.2D;
}

public boolean tick() {
    this.lastX = this.x;
    this.lastY = this.y;
    this.lastZ = this.z;
    this.x += this.motionX;
    this.y += this.motionY;
    this.z += this.motionZ;
    this.motionY -= GRAVITY;
    this.motionX *= DRAG;
    this.motionY *= DRAG;
    this.motionZ *= DRAG;
    if (this.y < this.floor) {
        this.y = this.floor;
        this.motionY *= BOUNCE;
        this.motionX *= 0.6D;
        this.motionZ *= 0.6D;
    }

    return ++this.age < this.lifetime;
}

public int alpha(float partialTick) {
    float left = 1.0F - (this.age + partialTick) / this.lifetime;
    return (int) (Mth.clamp(left * 2.0F, 0.0F, 1.0F) * 255.0F);
}

public static String amount(float value) {
    return Math.abs(value - Math.round(value)) < 0.05F ? Integer.toString(Math.round(value)) : String.format(Locale.ROOT, "%.1f", value);
}

public static DamageKind of(@Nullable DamageSource source) {
    if (source == null) {
        return GENERIC;
    }
    if (source.is(DamageTypeTags.IS_FIRE)) {
        return FIRE;
    }
    if (source.is(DamageTypeTags.IS_EXPLOSION)) {
        return EXPLOSION;
    }
    if (source.is(DamageTypeTags.IS_PROJECTILE)) {
        return PROJECTILE;
    }
    if (source.is(DamageTypeTags.IS_DROWNING)) {
        return DROWNING;
    }
    if (source.is(DamageTypeTags.IS_FREEZING)) {
        return FREEZING;
    }
    if (source.is(DamageTypeTags.IS_LIGHTNING)) {
        return LIGHTNING;
    }
    if (source.is(DamageTypeTags.IS_FALL)) {
        return FALL;
    }
    if (source.is(DamageTypes.STARVE)) {
        return STARVATION;
    }
    if (source.is(DamageTypes.CACTUS) || source.is(DamageTypes.SWEET_BERRY_BUSH)) {
        return CACTUS;
    }
    if (source.is(DamageTypes.MAGIC) || source.is(DamageTypes.INDIRECT_MAGIC) || source.is(DamageTypes.WITHER) || source.is(DamageTypes.DRAGON_BREATH)) {
        return MAGIC;
    }
    // Modded only: NeoForge also tags thorns, which stays a hit from the wearer on both loaders.
    if (source.is(MODDED_MAGIC) && moddedId(source) != null) {
        return MAGIC;
    }
    return source.getEntity() != null ? MELEE : GENERIC;
}

public int color(@Nullable DamageSource source) {
    Identifier id = this == GENERIC ? moddedId(source) : null;
    return id == null ? this.color : colorOf(id);
}

public static int colorOf(Identifier id) {
    // String.hashCode is fixed by the Java spec, so the colour never changes between launches or machines.
    int hash = Mth.murmurHash3Mixer(id.toString().hashCode());
    float hue = (hash & 0xFFFF) / 65536.0F;
    float saturation = 0.45F + ((hash >>> 16) & 0xFF) / 255.0F * 0.3F;
    float value = 0.85F + ((hash >>> 24) & 0xFF) / 255.0F * 0.15F;
    return Mth.hsvToRgb(hue, saturation, value);
}

private static @Nullable Identifier moddedId(@Nullable DamageSource source) {
    Identifier id = source == null ? null : source.typeHolder().unwrapKey().map(ResourceKey::identifier).orElse(null);
    return id == null || id.getNamespace().equals(Identifier.DEFAULT_NAMESPACE) ? null : id;
}

public Component label() {
    return Component.translatable("hud.assorteddamagenumbers.damage." + this.name().toLowerCase(Locale.ROOT));
}

public Component label(@Nullable DamageSource source) {
    Identifier id = this == GENERIC ? moddedId(source) : null;
    return id == null ? this.label() : Component.translatableWithFallback("hud.assorteddamagenumbers.damage." + id.toLanguageKey(), nameOf(id));
}

public static String nameOf(Identifier id) {
    String path = id.getPath().substring(id.getPath().lastIndexOf('/') + 1);
    return Arrays.stream(path.split("_")).filter(word -> !word.isEmpty())
            .map(word -> word.substring(0, 1).toUpperCase(Locale.ROOT) + word.substring(1)).collect(Collectors.joining(" "));
}

public DamageNumbersClientConfig() {
    final IConfigurationBuilder builder = Services.CONFIG.createBuilder(ConfigurationType.CLIENT_ONLY, Constants.MOD_ID + "-client");

    damageNumbersShowSource = builder.defineBoolean("damageNumbers.showSource", true, "Show what did the damage beside the number, as in -3 (Fire).");
    damageNumbersShowHealing = builder.defineBoolean("damageNumbers.showHealing", true, "Show healing as well as damage.");
    damageNumbersRange = builder.defineInteger("damageNumbers.range", 24, 4, 64, "How far away, in blocks, damage numbers are shown.");
    damageNumbersLifetime = builder.defineInteger("damageNumbers.lifetime", 40, 10, 200, "How long a damage number stays, in ticks. There are 20 ticks a second.");

    builder.setup();
}

