public void buildGeometry(VertexConsumer vertexConsumer, Camera camera, float tickDelta) {
    var cameraPos = camera.getPos();

    float particleX = (float) (prevPosX + (x - prevPosX) * (double) tickDelta - cameraPos.x);
    float particleY = (float) (prevPosY + (y - prevPosY) * (double) tickDelta - cameraPos.y);
    float particleZ = (float) (prevPosZ + (z - prevPosZ) * (double) tickDelta - cameraPos.z);

    Matrix4f matrix = new Matrix4f();
    matrix = matrix.translation(particleX, particleY, particleZ);
    matrix = matrix.rotate(camera.getRotation());
    matrix = matrix.rotate((float) Math.PI, 0.0F, 1.0F, 0.0F);
    matrix = matrix.scale(-0.025F, -0.025F, -0.025F);

    var client = MinecraftClient.getInstance();

    var textRenderer = client.textRenderer;
    var vertexConsumers = client.getBufferBuilders().getEntityVertexConsumers();

    float textX = textRenderer.getWidth(text) / -2.0F;
    float textY = 0.0F;

    int textColor = new Color(red, green, blue, alpha).getValue();

    textRenderer.draw(text, textX, textY, textColor, false, matrix, vertexConsumers, TextRenderer.TextLayerType.NORMAL, 0, 0xF000F0);
    vertexConsumers.draw();
}

public int getValue() {
    int value = 0;
    value |= convertComponent(a) << 24;
    value |= convertComponent(r) << 16;
    value |= convertComponent(g) << 8;
    value |= convertComponent(b);
    return value;
}

public static @NotNull Color lerp(@NotNull Color a, @NotNull Color b, float delta) {
    Objects.requireNonNull(a, "Argument 'a'");
    Objects.requireNonNull(b, "Argument 'b'");
    return new Color(
        a.r + (b.r - a.r) * delta,
        a.g + (b.g - a.g) * delta,
        a.b + (b.b - a.b) * delta,
        a.a + (b.a - a.a) * delta
    );
}

public static @NotNull Color valueOf(@NotNull String string) {
    Objects.requireNonNull(string, "Argument 'string'");

    var matcher = pattern.matcher(string);
    if (!matcher.matches()) {
        throw new IllegalArgumentException("Invalid color code syntax");
    }

    int value;

    var alpha = matcher.group(4);
    if (alpha != null) {
        value = parseHexComponent(alpha) << 24;
    } else {
        value = 0xFF000000;
    }

    value |= parseHexComponent(matcher.group(1)) << 16;
    value |= parseHexComponent(matcher.group(2)) << 8;
    value |= parseHexComponent(matcher.group(3));

    return new Color(value);
}

private static int convertComponent(float component) {
    return Math.max(Math.min((int) (component * 255.0F), 0xFF), 0);
}

public void fromJson(@NotNull JsonObject json) {
    json.entrySet().forEach(entry -> {
        switch (entry.getKey()) {
            case "isEnabled" -> isEnabled = entry.getValue().getAsBoolean();
            case "isPlayerDamageShown" -> isPlayerDamageShown = entry.getValue().getAsBoolean();
            case "colorSm" -> colorSm = Color.valueOf(entry.getValue().getAsString());
            case "colorMd" -> colorMd = Color.valueOf(entry.getValue().getAsString());
            case "colorLg" -> colorLg = Color.valueOf(entry.getValue().getAsString());
        }
    });
}

public void readConfig(@NotNull PathProvider paths) {
    try {
        fromJson(GSON.fromJson(Files.newBufferedReader(paths.getConfigFilePath()), JsonObject.class));
    } catch (NoSuchFileException cause) {
        DamageNumbers.LOGGER.error("Failed to read config, file not found, creating config");
        writeConfig(paths);
    } catch (IOException cause) {
        DamageNumbers.LOGGER.error("Failed to read config, IO error", cause);
    } catch (JsonParseException cause) {
        DamageNumbers.LOGGER.error("Failed to read config, JSON error", cause);
    } catch (Exception cause) {
        DamageNumbers.LOGGER.error("Failed to read config", cause);
    }
}

public void writeConfig(@NotNull PathProvider paths) {
    try {
        var pathFile = paths.getConfigFilePath();
        var pathTemp = paths.getConfigTempPath();
        Files.writeString(pathTemp, toJson());
        Files.move(pathTemp, pathFile, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
    } catch (IOException cause) {
        DamageNumbers.LOGGER.error("Failed to write new config, IO error", cause);
    } catch (Exception cause) {
        DamageNumbers.LOGGER.error("Failed to write new config", cause);
    }
}

